import time
from splunk.version import __version__ as splunk_version

def generate_base_telemetry_payload(info):
    """
    Generate the base telemetry payload used for any telemetry event.

    @type  info: dict
    @param info: A dictionary containing the type (string) of the event and the
                 data (dict), which contains the additional data to go along with
                 the event.

    @rtype: dict
    @return: The base telemetry payload.
    """
    if type(info) is not dict:
        raise TypeError('"info" parameter is not a dict')
    if 'type' not in info or 'data' not in info:
        raise ValueError('"info" parameter is malformed. Expected a dict with keys "type" and "data".')

    info['data']['splunkVersion'] = splunk_version
    jsonargs = {
        'type': 'event',
        'component': 'cherrypy.{}'.format(info['type']),
        'data': info['data'],
        "timestamp": round(time.time()),
        "optInRequired": 3
    }
    return jsonargs

def check_auth_params(app, owner, session_key):
    """
    Check the parameters that are going to be sent to /telemetry-metric are present
    If the parameter is None, the call will result in a 401 so we should prevent the 
    call from occurring

    @type  app: str
    @param app: app name for the request

    @type  owner: str
    @param owner: owner of the request

    @type  session_key: str
    @param session_key: session key to be used for the request


    @rtype: ValueError or None
    @return: Will throw a value error or return nothing
    """

    if owner is None or owner == '':
        raise ValueError('Failed to get current owner. owner=%s app=%s' % (owner, app))
    if app is None or app == '':
        raise ValueError('Failed to get current app. app=%s owner=%s' % (app, owner))
    
    if session_key is None or session_key == '':
        raise ValueError('Failed to get session key')
